export function startWheelEventLab({runPaidWheelActiveTimeline,compareWheelActiveTimelines,runWheelActiveTimeline,runWheelEventSequence,advanceDoomsdayAfterUseCard,advanceLightOfIntellectAfterKeeperSkill,advanceArachneAfterPursuit,runtimeFingerprint},doc=document){
  const $=id=>doc.getElementById(id);
  let pinned=null;
  const examples={
    doomsday:{schemaVersion:1,kind:'morimens-after-use-card-wheel-trigger',build:'pc-res144-build51',wheelId:'wheel-0029',refinementLevel:3,cardType:'Card_Strike',ownerAttack:1000,counter:0,strikecardDamagePlus:0},
    light:{schemaVersion:1,kind:'morimens-after-keeper-skill-wheel-trigger',build:'pc-res144-build51',wheelId:'wheel-0117',refinementLevel:3,counter:0,roll:100,matchingStrikeAvailable:true},
    arachne:{schemaVersion:1,kind:'morimens-after-pursuit-wheel-triggers',build:'pc-res144-build51',ownerUid:56,pursuitOwnerUid:56,basicDamagePer:150,wheels:[{slotId:'wheel-1',wheelId:'wheel-0128',refinementLevel:3,triggersUsed:0},{slotId:'wheel-2',wheelId:'wheel-0132',refinementLevel:3,triggersUsed:0}]},
    sequence:{schemaVersion:1,kind:'morimens-wheel-event-sequence',build:'pc-res144-build51',initialState:{doomsday:{refinementLevel:3,ownerAttack:1000,counter:0,baseStrikecardDamagePlus:0,wheelStrikecardDamagePlus:0},light:{refinementLevel:3,counter:0},arachne:{ownerUid:56,baseBasicDamagePer:150,wheelBasicDamagePer:0,wheels:[{slotId:'wheel-1',wheelId:'wheel-0128',refinementLevel:3,triggersUsed:0},{slotId:'wheel-2',wheelId:'wheel-0132',refinementLevel:3,triggersUsed:0}]}},steps:[{id:'keeper',type:'AFTER_KEEPER_SKILL',roll:100,matchingStrikeAvailable:true},{id:'strike-1',type:'AFTER_USE_CARD',cardType:'Card_Strike'},{id:'arachne-pursuit',type:'AFTER_PURSUIT',pursuitOwnerUid:56},{id:'turn-end',type:'AFTER_BOUT_END'},{id:'next-turn-pursuit',type:'AFTER_PURSUIT',pursuitOwnerUid:56}]},
    damage:{schemaVersion:1,kind:'morimens-wheel-active-timeline',build:'pc-res144-build51',snapshotStage:'battle-property-server-live',snapshotCompleteness:'complete-map',initialWheelState:{doomsday:{refinementLevel:3,ownerAttack:1000,counter:0,baseStrikecardDamagePlus:0,wheelStrikecardDamagePlus:0},light:null,arachne:{ownerUid:56,baseBasicDamagePer:0,wheelBasicDamagePer:0,wheels:[{slotId:'wheel-1',wheelId:'wheel-0128',refinementLevel:3,triggersUsed:0},{slotId:'wheel-2',wheelId:'wheel-0132',refinementLevel:3,triggersUsed:0}]}},baseCasterProperties:{crit:0,crit_damage:0,crit_damage_from_strikecard:0,crit_damage_per:0,strikecard_damage_plus:0},basePlayerProperties:{dimension_fix_per:0,basic_damage_per:0},initialTargetProperties:{hp:5000,max_hp:5000,block:0,be_damage_per:0,vulnerable_per:0},steps:[{id:'strike-1',type:'ACTIVE_HIT',baseValue:100,skillArgsPlus:0,tags:['Card_Strike'],cardProperties:{},cardContext:{present:false,instructionCard:false,stateTriggerAdd:false},targetContext:{critRoll:null,targetBattleTag:'Boss',targetStateIds:[]},hitContext:{damageSubtype:'Ordinary'}},{id:'after-strike-1',type:'AFTER_USE_CARD',cardType:'Card_Strike'},{id:'strike-2',type:'ACTIVE_HIT',baseValue:100,skillArgsPlus:0,tags:['Card_Strike'],cardProperties:{},cardContext:{present:false,instructionCard:false,stateTriggerAdd:false},targetContext:{critRoll:null,targetBattleTag:'Boss',targetStateIds:[]},hitContext:{damageSubtype:'Ordinary'}},{id:'after-pursuit',type:'AFTER_PURSUIT',pursuitOwnerUid:56},{id:'strike-3',type:'ACTIVE_HIT',baseValue:100,skillArgsPlus:0,tags:['Card_Strike'],cardProperties:{},cardContext:{present:false,instructionCard:false,stateTriggerAdd:false},targetContext:{critRoll:null,targetBattleTag:'Boss',targetStateIds:[]},hitContext:{damageSubtype:'Ordinary'}}]}
  };
  const conditions={cardExists:true,inHand:true,judgeCost:true,commandExists:true,dead:false,strike:true,allowIgnoreCost:false,cardUseless:0,ownerUseless:0,coma:0,comaImmunity:0,ownerForbid:0,playerForbid:0,ownerForbidStrike:0,playerForbidStrike:0};
  const paidAction=(id,cost)=>({id,cardInstanceId:`card-${id}`,cardType:'Card_Strike',costInput:{cfgCost:String(cost),originCost:cost,delta:0,harmonize:0,fixedSwitches:{},keeper:false,keeperCost:null,pvp:false},conditions:{...conditions},effects:[{id:`${id}:hit`,type:'ACTIVE_HIT',baseValue:100,skillArgsPlus:0,tags:['Card_Strike'],cardProperties:{},cardContext:{present:false,instructionCard:false,stateTriggerAdd:false},targetContext:{critRoll:null,targetBattleTag:'Boss',targetStateIds:[]},hitContext:{damageSubtype:'Ordinary'}}]});
  examples.paid={schemaVersion:1,kind:'morimens-paid-wheel-active-timeline',build:'pc-res144-build51',initialEnergy:4,snapshotStage:'battle-property-server-live',snapshotCompleteness:'complete-map',initialWheelState:{doomsday:{refinementLevel:3,ownerAttack:1000,counter:0,baseStrikecardDamagePlus:0,wheelStrikecardDamagePlus:0},light:null,arachne:null},baseCasterProperties:{crit:0,crit_damage:0,crit_damage_from_strikecard:0,crit_damage_per:0,strikecard_damage_plus:0},basePlayerProperties:{dimension_fix_per:0},initialTargetProperties:{hp:2000,max_hp:2000,block:0,be_damage_per:0,vulnerable_per:0},actions:[paidAction('strike-1',2),paidAction('strike-2',2)]};
  const calculate=input=>{
    if(input.kind==='morimens-after-use-card-wheel-trigger')return advanceDoomsdayAfterUseCard(input);
    if(input.kind==='morimens-after-keeper-skill-wheel-trigger')return advanceLightOfIntellectAfterKeeperSkill(input);
    if(input.kind==='morimens-after-pursuit-wheel-triggers')return advanceArachneAfterPursuit(input);
    if(input.kind==='morimens-wheel-event-sequence')return runWheelEventSequence(input);
    if(input.kind==='morimens-wheel-active-timeline')return runWheelActiveTimeline(input);
    if(input.kind==='morimens-wheel-active-comparison')return compareWheelActiveTimelines(input,{runtimeFingerprint});
    if(input.kind==='morimens-paid-wheel-active-timeline')return runPaidWheelActiveTimeline(input);
    throw new Error('Unsupported Wheel event request kind');
  };
  const render=input=>{
    const result=calculate(input);let summary;
    if(result.kind==='morimens-after-use-card-wheel-trigger-result')summary=`Strike flat damage ${result.transition.strikecardDamagePlusBefore} → ${result.transition.strikecardDamagePlusAfter}; counter ${result.transition.counterBefore} → ${result.transition.counterAfter}`;
    else if(result.kind==='morimens-after-keeper-skill-wheel-trigger-result')summary=`Move request ${result.transition.moveRequested?'passed':'did not pass'}; ${result.transition.movedCardCount} card moved; counter ${result.transition.counterBefore} → ${result.transition.counterAfter}`;
    else if(result.kind==='morimens-after-pursuit-wheel-triggers-result')summary=`Team damage amplification ${result.basicDamagePerBefore}% → ${result.basicDamagePerAfter}% (${result.addedBasicDamagePer>=0?'+':''}${result.addedBasicDamagePer})`;
    else if(result.kind==='morimens-wheel-event-sequence-result')summary=`${result.trace.length} events · final Strike flat ${result.finalState.doomsday?.strikecardDamagePlus??'not tracked'} · final team amplification ${result.finalState.arachne?.basicDamagePer??'not tracked'}`;
    else if(result.kind==='morimens-wheel-active-timeline-result')summary=`${result.executedSteps} steps · ${result.modeledHpLost} modeled HP lost · final Strike flat ${result.finalWheelState.doomsday?.strikecardDamagePlus??'not tracked'} · final team amplification ${result.finalWheelState.arachne?.basicDamagePer??'not tracked'}`;
    else if(result.kind==='morimens-paid-wheel-active-timeline-result')summary=`${result.acceptedActions} accepted cards · ${result.modeledEnergyLost} energy spent · ${result.modeledHpLost} modeled HP lost · final Strike flat ${result.finalWheelState.doomsday?.strikecardDamagePlus??'not tracked'}`;
    else summary=`${result.orderOnly?'Order-only':'Input'} comparison · ${result.modeledHpLostDelta===null?'incomplete':`${result.modeledHpLostDelta>=0?'+':''}${result.modeledHpLostDelta} modeled HP lost`} · ${result.alignedSteps.length} aligned steps`;
    $('result').hidden=false;$('summary').textContent=summary;$('scope').textContent=`${result.event??(result.kind==='morimens-wheel-active-comparison-result'?'aligned comparison':'ordered events')} · ${result.status} · finalDamage is ${result.finalDamage}`;$('output').textContent=JSON.stringify({...result,runtimeFingerprint},null,2);$('error').textContent='';
  };
  $('run').onclick=()=>{try{render(JSON.parse($('input').value));}catch(error){$('result').hidden=true;$('error').textContent=error.message;}};
  $('pin').onclick=()=>{try{const input=JSON.parse($('input').value);if(input.kind!=='morimens-wheel-active-timeline')throw new Error('Pin requires a Wheel + damage timeline');runWheelActiveTimeline(input);pinned=JSON.parse(JSON.stringify(input));$('pin-status').textContent=`Pinned ${input.steps.length} steps to verified runtime ${runtimeFingerprint.slice(0,12)}…`;$('error').textContent='';}catch(error){$('error').textContent=error.message;}};
  $('compare').onclick=()=>{try{if(!pinned)throw new Error('Pin a Wheel + damage timeline first');const candidate=JSON.parse($('input').value);if(candidate.kind!=='morimens-wheel-active-timeline')throw new Error('Comparison candidate must be a Wheel + damage timeline');render({schemaVersion:1,kind:'morimens-wheel-active-comparison',runtimeFingerprint,baseline:pinned,candidate});}catch(error){$('result').hidden=true;$('error').textContent=error.message;}};
  for(const id of Object.keys(examples))$(id).onclick=()=>{$('input').value=JSON.stringify(examples[id],null,2);render(examples[id]);};
  $('runtime-status').textContent=`Verified local engine ${runtimeFingerprint.slice(0,12)}…`;
}
